/**
 * Live incident events in neatlogs. When something goes wrong while an agent works, the call site
 * reports it here and it becomes a neatlogs log() record at level warn/error, tied to the span that
 * is active at that moment (the probe, the guard, the LLM call, ...):
 *
 *   message   "incident <kind> [WARN|ERROR]: <summary>"
 *   attrs     notary.incident.id / .kind / .severity / .subject, notary.incident.spanId / .traceId
 *             (the span it happened in), notary.runId, plus small call-site facts
 *             (the SDK records each as a `log.<key>` attribute)
 *
 * Resolutions are logged the same way at level info ("incident <id> resolved: <summary>").
 *
 * The incident id is deterministic — incidentId(kind, subject) — and src/incidents/derive.ts uses
 * the same function on the recorded data, so the log event in neatlogs and the row in
 * runs/<runId>/incidents.json carry the same `notary.incident.id`. At the end of a run,
 * recordRunIncidents emits every derived incident that was not already reported live in this process
 * (so each incident reaches neatlogs exactly once per process).
 *
 * Never throws; no-op (returns false) when tracing is off. Summaries are generated by code and pass
 * through the trace module's secret masking.
 */
import { createHash } from "node:crypto";
import type { IncidentKind, IncidentResolution, IncidentSeverity } from "../schema/incidents.js";
import { currentSpanIds, traceLogAt } from "../trace/index.js";
import type { TraceAttrs } from "../trace/index.js";

/** "inc-" + sha256(kind | subject)[:16]. Subjects are globally unique record keys (anomaly id, probe id, span id, ...). */
export function incidentId(kind: IncidentKind, subject: string): string {
  return `inc-${createHash("sha256").update(`${kind}|${subject}`).digest("hex").slice(0, 16)}`;
}

const reported = new Set<string>();
const resolved = new Set<string>();

/** Incident ids already sent to neatlogs by this process. */
export function reportedIncidentIds(): ReadonlySet<string> {
  return reported;
}

/** Forget what was reported (tests). */
export function resetReportedIncidents(): void {
  reported.clear();
  resolved.clear();
}

export function logLevelFor(severity: IncidentSeverity): "warn" | "error" {
  return severity === "error" ? "error" : "warn";
}

export type LiveIncident = {
  kind: IncidentKind;
  /** The record key the id is derived from (must match what derive.ts uses for this kind). */
  subject: string;
  severity: IncidentSeverity;
  summary: string;
  /** Extra facts (ids, status codes, ...). Never secrets or prompts. */
  attrs?: TraceAttrs;
  /** The span it happened in, when not the active one. */
  span?: { traceId: string; spanId: string };
  /** A precomputed id (derive.ts); default incidentId(kind, subject). */
  id?: string;
};

/** Send one incident to neatlogs as a warn/error log record. Returns its id. Idempotent per process. */
export function reportIncident(i: LiveIncident): string {
  const id = i.id ?? incidentId(i.kind, i.subject);
  if (reported.has(id)) return id;
  try {
    const span = i.span ?? currentSpanIds();
    const ok = traceLogAt(logLevelFor(i.severity), `incident ${i.kind} [${i.severity === "error" ? "ERROR" : "WARN"}]: ${i.summary}`, {
      "notary.incident.id": id,
      "notary.incident.kind": i.kind,
      "notary.incident.severity": i.severity,
      "notary.incident.subject": i.subject,
      ...(span ? { "notary.incident.traceId": span.traceId, "notary.incident.spanId": span.spanId } : {}),
      ...i.attrs,
    });
    if (ok) reported.add(id);
  } catch {
    // incident reporting must never break the traced work
/**
 * Publish incidents for the bundles already in the dashboard (real: packages/web/public/bundles,
 * fixture: .../bundles/fixture) into packages/web/public/incidents[/fixture], derived from
 * packages/core/runs/** — no new runs; nothing under public/bundles is written.
 *   pnpm --filter @notary/core publish:incidents
 */
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { publishDashboardIncidents } from "../src/incidents/record.js";

const runs = fileURLToPath(new URL("../runs/", import.meta.url));
const web = fileURLToPath(new URL("../../web/public/bundles/", import.meta.url));
const incidents = fileURLToPath(new URL("../../web/public/incidents/", import.meta.url));

const real = await publishDashboardIncidents(web, incidents, { sample: false, runsDirs: [runs] });
const fixture = await publishDashboardIncidents(join(web, "fixture"), join(incidents, "fixture"), { sample: true, runsDirs: [join(runs, "demo"), join(runs, "demo-change-api")] });
for (const [label, r] of [["real", real], ["fixture", fixture]] as const) {
  console.log(`${label}: ${r.index.incidents} incident(s) from ${r.index.runs} run(s) -> ${r.index.path}`);
  for (const s of r.skipped) console.log(`  skipped ${s.runId}: ${s.reason}`);
}

