// One-off: publish the three replay outputs in packages/core/runs/<id>-replay/ to packages/web/public/bundles
// (bundle + index entry + timeline), the same calls `notary export` makes. Run from packages/core with tsx.
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { verifyBundle, writeBundle } from "./src/bundle/index.js";
import { collectBundles } from "./src/export/collect.js";
import { publishTimeline } from "./src/timeline/write.js";

const core = resolve(".");
const runs = join(core, "runs");
const web = resolve(core, "..", "web", "public", "bundles");
const ids = ["notarize-crustdata-20261012T011404Z-replay", "recon-dodo-20261012T013640Z-replay", "notarize-dodo-20261012T014032Z-replay"];
const context = collectBundles(runs).bundles.map((b) => b.bundle);
for (const id of ids) {
  const v = verifyBundle(JSON.parse(readFileSync(join(runs, id, `${id}.json`), "utf8")));
  if (!v.ok) throw new Error(`${id}: ${v.error}`);
  await writeBundle(v.bundle, web);
  await publishTimeline(v.bundle, web, { expectSample: false, runDir: join(runs, id), context });
  console.log(`published ${id} ${v.bundle.contentHash.slice(0, 12)}`);
}

